mapper.select:
SELECT 
FROM fin_ex_route_memory_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND item_type = 'ROUTE'
  AND status = 'ACTIVE'
ORDER BY created_at DESC
LIMIT #{limit}

SELECT 
FROM fin_ex_route_memory_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND item_type = 'CLARIFY'
  AND status = 'ACTIVE'
ORDER BY created_at ASC

mapper.update:
UPDATE fin_ex_route_memory_t
SET status = 'FOLDED',
    folded_at = #{foldedAt},
    updated_at = #{foldedAt}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND item_type = 'CLARIFY'
  AND status = 'ACTIVE'
